    p=s.ROOT/node['operad_collection'];collection=yaml.safe_load(p.read_bytes());collection['latest_review']['status']='reviewed_with_final_native_integration';p.write_bytes(yaml.safe_dump(collection,sort_keys=False,allow_unicode=True,width=100).encode());paths.add(p)
